import"./chunk-VC46IEJQ.js";var e=(a,o)=>({en:a,zh:o}),t=(a,o,n,r,h,i,d,l,s)=>({name:a,desc:o,tour:n,...s?{spoiler:s}:{},source:{confidence:r,refs:h,book:i,unknown:d,interpretation:l}}),c={id:"isle-of-faces",intro:e("An island in the middle of the God's Eye, wooded with ancient weirwoods whose white trunks still bear carved faces. Here, legend says, the First Men and the Children of the Forest made their Pact, and the green men are said to keep it still.","\u795E\u773C\u6E56\u4E2D\u592E\u7684\u4E00\u5EA7\u5C9B\u5C7F\uFF0C\u6797\u4E2D\u53E4\u8001\u7684\u9C7C\u6881\u6728\u767D\u5E72\u4E0A\u4F9D\u65E7\u523B\u7740\u4EBA\u8138\u3002\u4F20\u8BF4\u5148\u6C11\u4E0E\u68EE\u6797\u4E4B\u5B50\u5728\u6B64\u7F14\u7ED3\u76DF\u7EA6\uFF0C\u636E\u8BF4\u81F3\u4ECA\u4ECD\u6709\u7EFF\u4EBA\u5B88\u62A4\u7740\u8FD9\u91CC\u3002"),notes:e("From the novels and TWOIAF: the island in the lake, weirwoods carved with faces, the legendary green men who tend it, its survival as a refuge of the old gods, and its place in the story of the Pact. Invented here: the grove layout, the stones, the huts, the landing, the pool and all measurements. Harrenhal appears only as a distant silhouette on the far shore.","\u51FA\u81EA\u5C0F\u8BF4\u4E0E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\uFF1A\u6E56\u4E2D\u5C9B\u5C7F\u3001\u523B\u6709\u4EBA\u8138\u7684\u9C7C\u6881\u6728\u3001\u4F20\u8BF4\u4E2D\u5B88\u62A4\u6B64\u5C9B\u7684\u7EFF\u4EBA\u3001\u6B64\u5730\u4F5C\u4E3A\u65E7\u795E\u4FE1\u4EF0\u6700\u540E\u5E87\u62A4\u6240\u7684\u5730\u4F4D\uFF0C\u4EE5\u53CA\u5B83\u5728\u76DF\u7EA6\u6545\u4E8B\u4E2D\u7684\u4F4D\u7F6E\u3002\u672C\u573A\u666F\u81EA\u884C\u8BBE\u8BA1\uFF1A\u6797\u5730\u5E03\u5C40\u3001\u7ACB\u77F3\u3001\u5C0F\u5C4B\u3001\u767B\u5CB8\u5904\u3001\u6C34\u6F6D\u53CA\u4E00\u5207\u5C3A\u5BF8\u3002\u8FDC\u5CB8\u7684\u8D6B\u4F26\u5821\u4EC5\u4EE5\u526A\u5F71\u793A\u610F\u3002"),tour:["landing","ring-of-faces","heart-tree","dark-pool","pact-stones","green-men","red-leaves","far-shore","god-s-eye"],sources:[{ref:"agot",checked:"memory",note:e("Bran's lessons and Old Nan's tales mention the Pact, the Isle of Faces and the green men; recalled, not re-read.","\u5E03\u5170\u7684\u8BFE\u4E1A\u4E0E\u8001\u5976\u5988\u7684\u6545\u4E8B\u63D0\u5230\u76DF\u7EA6\u3001\u5343\u9762\u5C7F\u4E0E\u7EFF\u4EBA\uFF1B\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002")},{ref:"twoiaf",checked:"memory",note:e("The Pact between the First Men and the Children on the isle, and the green men; recalled, and the wording of that history may not be exact.","\u5148\u6C11\u4E0E\u68EE\u6797\u4E4B\u5B50\u5728\u5C9B\u4E0A\u7F14\u7EA6\uFF0C\u4EE5\u53CA\u7EFF\u4EBA\u7684\u8BB0\u8FF0\uFF1B\u51ED\u8BB0\u5FC6\uFF0C\u76F8\u5173\u63AA\u8F9E\u672A\u5FC5\u51C6\u786E\u3002")},{ref:"awoiaf",checked:"not-accessed",note:e("Not consulted this pass; the scene avoids details the wiki might add.","\u672C\u6B21\u672A\u67E5\u9605\uFF1B\u573A\u666F\u56DE\u907F\u4E86\u7EF4\u57FA\u53EF\u80FD\u8865\u5145\u7684\u7EC6\u8282\u3002")}],landmarks:{"heart-tree":t(e("The Heart Tree","\u5FC3\u6811"),e("A great weirwood with a deep-cut face whose eyes seem to weep red sap.","\u4E00\u682A\u5DE8\u5927\u7684\u9C7C\u6881\u6728\uFF0C\u523B\u75D5\u6DF1\u6DF1\u7684\u9762\u5B54\u4E0A\uFF0C\u53CC\u773C\u4EFF\u4F5B\u6DCC\u7740\u7EA2\u8272\u7684\u6811\u6DB2\u3002"),e("An ancient carved face under a crown of red leaves.","\u4E00\u5F20\u53E4\u8001\u7684\u96D5\u523B\u9762\u5B54\uFF0C\u5934\u9876\u7EA2\u53F6\u5982\u51A0\u3002"),"low",["agot","twoiaf"],e("Weirwoods with carved faces grow on the island; weirwood sap is red, and carved faces often seem to weep it.","\u5C9B\u4E0A\u751F\u957F\u7740\u523B\u6709\u4EBA\u8138\u7684\u9C7C\u6881\u6728\uFF1B\u9C7C\u6881\u6728\u7684\u6811\u6DB2\u5448\u7EA2\u8272\uFF0C\u523B\u51FA\u7684\u9762\u5B54\u5E38\u4F3C\u6DCC\u7740\u8840\u6CEA\u3002"),e("Whether any single tree stands above the rest, and where.","\u662F\u5426\u6709\u4E00\u682A\u683C\u5916\u9AD8\u5927\u7684\u6811\uFF0C\u53C8\u5728\u4F55\u5904\u3002"),e("One large central tree is invented as a focal point.","\u4E3A\u7A81\u51FA\u7126\u70B9\uFF0C\u81EA\u884C\u8BBE\u4E86\u4E00\u682A\u5C45\u4E2D\u7684\u5927\u6811\u3002")),"ring-of-faces":t(e("Ring of Faces","\u4EBA\u8138\u6811\u73AF"),e("A ring of white-barked weirwoods, each carved with its own solemn face turned inward.","\u4E00\u5708\u767D\u76AE\u9C7C\u6881\u6728\uFF0C\u6BCF\u682A\u90FD\u523B\u7740\u4E00\u5F20\u795E\u60C5\u8083\u7A46\u3001\u5404\u4E0D\u76F8\u540C\u7684\u9762\u5B54\uFF0C\u9F50\u9F50\u671D\u5411\u5708\u5185\u3002"),e("Dozens of carved faces, each different, all watching the centre.","\u6570\u5341\u5F20\u9762\u5B54\u5404\u4E0D\u76F8\u540C\uFF0C\u5374\u90FD\u51DD\u671B\u7740\u5708\u5FC3\u3002"),"medium",["agot","twoiaf"],e("Weirwoods carved with faces are what give the island its name; the Andals who felled weirwoods elsewhere never reached it.","\u523B\u6709\u4EBA\u8138\u7684\u9C7C\u6881\u6728\u4F7F\u6B64\u5C9B\u5F97\u540D\uFF1B\u5B89\u8FBE\u5C14\u4EBA\u5728\u522B\u5904\u780D\u4F10\u9C7C\u6881\u6728\uFF0C\u5374\u59CB\u7EC8\u672A\u80FD\u767B\u4E0A\u6B64\u5C9B\u3002"),e("How many trees there are and how they stand.","\u6811\u7684\u6570\u91CF\u4E0E\u6392\u5E03\u3002"),e("A ring of twelve trees with a loose outer scatter.","\u5341\u4E8C\u682A\u6210\u73AF\uFF0C\u5916\u56F4\u96F6\u6563\u5206\u5E03\u82E5\u5E72\u3002")),"pact-stones":t(e("Pact Stones","\u76DF\u7EA6\u77F3"),e("Low standing stones marking where, by tradition, the Pact was sworn.","\u51E0\u5757\u4F4E\u77EE\u7684\u7ACB\u77F3\uFF0C\u6807\u793A\u7740\u4F20\u8BF4\u4E2D\u7ACB\u7EA6\u7684\u5730\u65B9\u3002"),e("Legend says the First Men and the Children made their peace on this isle.","\u4F20\u8BF4\u5148\u6C11\u4E0E\u68EE\u6797\u4E4B\u5B50\u5728\u8FD9\u5EA7\u5C9B\u4E0A\u63E1\u624B\u8A00\u548C\u3002"),"low",["agot","twoiaf"],e("Tradition places the making of the Pact on the Isle of Faces; no monument is described.","\u4F20\u8BF4\u76DF\u7EA6\u5728\u5343\u9762\u5C7F\u4E0A\u7F14\u7ED3\uFF1B\u4E66\u4E2D\u5E76\u672A\u63D0\u5230\u4EFB\u4F55\u7EAA\u5FF5\u7269\u3002"),e("Whether any stones or markers exist.","\u662F\u5426\u6709\u7ACB\u77F3\u6216\u6807\u8BB0\u3002"),e("The seven small stones are purely invented.","\u4E03\u5757\u5C0F\u77F3\u7EAF\u5C5E\u865A\u6784\u3002")),"green-men":t(e("Green Men's Huts","\u7EFF\u4EBA\u5C0F\u5C4B"),e("Two small thatched huts at the edge of the grove, for the green men said to keep the island.","\u6797\u8FB9\u4E24\u95F4\u8305\u8349\u5C0F\u5C4B\uFF0C\u636E\u8BF4\u5C5E\u4E8E\u5B88\u62A4\u6B64\u5C9B\u7684\u7EFF\u4EBA\u3002"),e("The green men are said to tend the grove still; few claim to have seen them.","\u636E\u8BF4\u7EFF\u4EBA\u81F3\u4ECA\u4ECD\u5728\u7167\u770B\u8FD9\u7247\u6797\u5B50\uFF0C\u4F46\u81EA\u79F0\u89C1\u8FC7\u4ED6\u4EEC\u7684\u4EBA\u5BE5\u5BE5\u65E0\u51E0\u3002"),"low",["agot","twoiaf"],e("Legend says an order of green men has kept the isle since the Pact; whether they survive is uncertain.","\u4F20\u8BF4\u81EA\u76DF\u7EA6\u4EE5\u6765\uFF0C\u4FBF\u6709\u4E00\u7FA4\u7EFF\u4EBA\u5B88\u62A4\u6B64\u5C9B\uFF1B\u4ED6\u4EEC\u662F\u5426\u5C1A\u5B58\uFF0C\u65E0\u4EBA\u80FD\u786E\u5B9A\u3002"),e("Whether they exist, where they live and how they are organised.","\u4ED6\u4EEC\u662F\u5426\u5B58\u5728\u3001\u5C45\u4E8E\u4F55\u5904\u3001\u5982\u4F55\u7EC4\u7EC7\u3002"),e("Two huts and a thread of smoke are invented.","\u4E24\u95F4\u5C0F\u5C4B\u4E0E\u4E00\u7F15\u708A\u70DF\u5747\u4E3A\u865A\u6784\u3002")),landing:t(e("The Landing","\u767B\u5CB8\u5904"),e("A plain wooden pier on the south shore where boats come in out of the mist.","\u5357\u5CB8\u4E00\u5EA7\u7B80\u6734\u7684\u6728\u6808\u6865\uFF0C\u5C0F\u8239\u4ECE\u96FE\u4E2D\u9760\u5CB8\u3002"),e("Visitors arrive by boat out of the mist; the isle does not welcome crowds.","\u6765\u5BA2\u4E58\u821F\u81EA\u96FE\u4E2D\u800C\u81F3\uFF1B\u6B64\u5C9B\u5E76\u4E0D\u6B22\u8FCE\u4EBA\u6F6E\u3002"),"low",["maps"],e("The island lies in the middle of a lake, so it can only be reached by water.","\u5C0F\u5C9B\u4F4D\u4E8E\u6E56\u5FC3\uFF0C\u53EA\u80FD\u7ECF\u6C34\u8DEF\u62B5\u8FBE\u3002"),e("Whether any landing place exists.","\u662F\u5426\u6709\u6B63\u5F0F\u7684\u767B\u5CB8\u5904\u3002"),e("A short pier and a rowing boat are invented.","\u77ED\u6808\u6865\u4E0E\u4E00\u6761\u5212\u8247\u5747\u4E3A\u865A\u6784\u3002")),"red-leaves":t(e("Red Leaves","\u7EA2\u53F6"),e("Weirwood leaves are deep red, shaped like hands; here they drift down and carpet the ground.","\u9C7C\u6881\u6728\u7684\u53F6\u5B50\u6DF1\u7EA2\uFF0C\u5F62\u5982\u624B\u638C\uFF1B\u5728\u8FD9\u91CC\u5B83\u4EEC\u7F13\u7F13\u98D8\u843D\uFF0C\u94FA\u6EE1\u4E00\u5730\u3002"),e("Red leaves drift down without a breeze.","\u65E0\u98CE\u4E4B\u65F6\uFF0C\u7EA2\u53F6\u4E5F\u6084\u7136\u98D8\u843D\u3002"),"high",["agot"],e("Weirwoods have white bark and red, hand-shaped leaves.","\u9C7C\u6881\u6728\u6811\u76AE\u6D01\u767D\uFF0C\u53F6\u7247\u8840\u7EA2\uFF0C\u5F62\u5982\u624B\u638C\u3002"),e("Whether and when they shed their leaves.","\u662F\u5426\u843D\u53F6\u3001\u4F55\u65F6\u843D\u53F6\u3002"),e("The constant gentle leaf-fall is visual licence.","\u6301\u7EED\u8F7B\u843D\u7684\u7EA2\u53F6\u53EA\u662F\u89C6\u89C9\u6E32\u67D3\u3002")),"dark-pool":t(e("Dark Pool","\u5E7D\u6F6D"),e("A still black pool beneath the heart tree, as in Winterfell's godswood.","\u5FC3\u6811\u4E0B\u7684\u4E00\u6F6D\u5E7D\u9ED1\u9759\u6C34\uFF0C\u4E00\u5982\u4E34\u51AC\u57CE\u7684\u795E\u6728\u6797\u3002"),e("A still, black pool, borrowed from the godswoods of the North.","\u4E00\u6F6D\u5E7D\u9ED1\u9759\u6C34\uFF0C\u501F\u81EA\u5317\u5883\u795E\u6728\u6797\u7684\u666F\u81F4\u3002"),"low",["agot"],e("Winterfell's heart tree stands beside a black pool; nothing similar is described on the isle.","\u4E34\u51AC\u57CE\u7684\u5FC3\u6811\u65C1\u6709\u4E00\u6F6D\u9ED1\u6C34\uFF1B\u4E66\u4E2D\u672A\u63CF\u5199\u6B64\u5C9B\u6709\u7C7B\u4F3C\u6C34\u6F6D\u3002"),e("Whether the isle has any pool.","\u5C9B\u4E0A\u662F\u5426\u6709\u6C34\u6F6D\u3002"),e("Added to echo the Winterfell godswood.","\u4E3A\u547C\u5E94\u4E34\u51AC\u57CE\u7684\u795E\u6728\u6797\u800C\u6DFB\u52A0\u3002")),"far-shore":t(e("Far Shore","\u5BF9\u5CB8"),e("Across the water to the north, the fire-slumped towers of Harrenhal break the skyline.","\u9694\u6C34\u5317\u671B\uFF0C\u8D6B\u4F26\u5821\u88AB\u70C8\u7130\u7194\u584C\u7684\u5854\u697C\u523A\u7834\u5929\u9645\u3002"),e("Look north across the mist: Harrenhal's melted towers.","\u8D8A\u8FC7\u96FE\u6C14\u5317\u671B\uFF1A\u4FBF\u662F\u8D6B\u4F26\u5821\u7194\u584C\u7684\u5854\u697C\u3002"),"medium",["acok","maps"],e("Harrenhal stands on the northern shore of the God's Eye.","\u8D6B\u4F26\u5821\u5750\u843D\u5728\u795E\u773C\u6E56\u5317\u5CB8\u3002"),e("Whether it can actually be seen from the island.","\u4ECE\u5C9B\u4E0A\u662F\u5426\u771F\u80FD\u671B\u89C1\u3002"),e("A faint silhouette across the water to the north.","\u5317\u9762\u6C34\u4E0A\u4E00\u9053\u6DE1\u6DE1\u7684\u526A\u5F71\u3002")),"god-s-eye":t(e("The God's Eye","\u795E\u773C\u6E56"),e("The great lake that surrounds the island, grey and still.","\u73AF\u7ED5\u5C0F\u5C9B\u7684\u5927\u6E56\uFF0C\u7070\u8499\u800C\u5E73\u9759\u3002"),e("The God's Eye: wide, grey and wrapped in mist.","\u795E\u773C\u6E56\uFF1A\u8FBD\u9614\u3001\u7070\u8499\u3001\u96FE\u6C14\u7F2D\u7ED5\u3002"),"high",["maps","twoiaf"],e("A large lake in the riverlands with the Isle of Faces at its centre.","\u6CB3\u95F4\u5730\u7684\u4E00\u5EA7\u5927\u6E56\uFF0C\u6E56\u5FC3\u4FBF\u662F\u5343\u9762\u5C7F\u3002"),e("Its depth and currents.","\u6E56\u6C34\u6DF1\u5EA6\u4E0E\u6C34\u6D41\u3002"),e("The banks of mist are atmosphere.","\u96FE\u6C14\u53EA\u662F\u6C1B\u56F4\u6E32\u67D3\u3002"))}};export{c as default};
